#!/bin/sh
# Regenerate build-frozen IL2CPP symbols after a VRChat update. Read-only with
# respect to game files; writes only generated files in this repository and a
# factual entry in AGENTS.md §17.
set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$ROOT"
GAME=${1:-"$HOME/.local/share/Steam/steamapps/common/VRChat"}
GA="$GAME/GameAssembly.dll"
[ -f "$GA" ] || { printf 'no GameAssembly.dll at %s\n' "$GA" >&2; exit 2; }

new_hash=$(sha256sum "$GA")
new_hash=${new_hash%% *}
old_hash=$(uv run --no-project python -c 'import re;print(re.search(r"GAMEASSEMBLY_SHA256: &str = \"([0-9a-f]+)\"",open("crates/hromatite-core/src/symbols.rs").read()).group(1))')

if [ "$new_hash" = "$old_hash" ]; then
    uv run --no-project python tools/api_map.py --check
    printf 'build unchanged: %s; generated files verified\n' "$old_hash"
    exit 0
fi

printf 'new build: %s -> %s\n' "$old_hash" "$new_hash"
uv run --no-project python tools/symmap.py --game-dir "$GAME"
uv run --no-project python tools/api_map.py --game-dir "$GAME"
version=$(uv run --no-project python -c 'import re;print(re.search(r"UNITY_VERSION: &str = \"([^\"]+)\"",open("crates/hromatite-core/src/symbols.rs").read()).group(1))')
timestamp=$(date -Iseconds)
cat >>AGENTS.md <<EOF

### $timestamp — Auto-refresh IL2CPP symbols after game update

- Unity: $version
- GameAssembly SHA-256: $new_hash
- Generated by tools/refresh.sh: symmap.py, api_map.py.
- API anchor changes still require live re-verification; no identities were
  inferred from canonical stub order.
EOF
printf 'updated generated files; inspect git diff, then commit and append the commit id to AGENTS.md §17\n'
